"<!doctype html><html lang='vi'><head><meta charset='utf-8'><meta name='viewport' content='width=device-width,initial-scale=1'><meta name='color-scheme' content='dark'><title>AUBOT | Kết nối</title><link rel='stylesheet' href='/ui.css?v=5'><style>"
".stack{display:grid;gap:10px}.config{padding:0;overflow:hidden}.config>summary{gap:10px;min-height:62px;padding:10px 16px}.body{padding:16px}.static{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:11px}.tools,.save{display:flex;align-items:center;justify-content:space-between;gap:10px}.tools{margin-bottom:12px}.wifi-tools{justify-content:flex-end}.save{margin-top:14px}.save .message{flex:1}.mode-note{padding:10px;border:1px solid var(--line2);border-radius:9px;color:var(--muted);overflow-wrap:anywhere}.network-live{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:8px;margin:0 0 14px}.network-live-item{min-width:0;padding:12px 13px;border:1px solid var(--line2);border-radius:10px;background:var(--glass2)}.network-live-head{display:flex;align-items:center;justify-content:space-between;gap:8px}.network-live-head small{color:var(--muted);font-size:10px;font-weight:800;letter-spacing:.05em}.network-state{display:inline-flex;align-items:center;gap:5px;color:var(--muted);font-size:9px;font-weight:800}.network-state:before{content:'';width:7px;height:7px;border-radius:50%;background:#64748b}.network-state.ok{color:#a7f3d0}.network-state.ok:before{background:var(--success)}.network-state.warn{color:#fde68a}.network-state.warn:before{background:var(--warning)}.network-state.bad{color:#fecaca}.network-state.bad:before{background:var(--danger)}.network-ip{display:block;overflow:hidden;margin-top:7px;color:var(--text);font:750 16px ui-monospace,SFMono-Regular,Consolas,monospace;text-overflow:ellipsis;white-space:nowrap}.network-meta{min-height:18px;margin:3px 0 0;overflow:hidden;color:var(--muted);font-size:11px;text-overflow:ellipsis;white-space:nowrap}.wifi-results{display:grid;gap:7px;margin:0 0 12px}.wifi-row{display:flex;align-items:center;justify-content:space-between;gap:10px;min-height:44px;padding:7px 10px;border:1px solid var(--line2);border-radius:8px;background:var(--glass2)}.wifi-row button{min-width:0;flex:1;border:0;background:transparent;color:var(--text);font-weight:650;text-align:left;cursor:pointer}.wifi-row button:hover{color:var(--cyan)}.wifi-rssi{color:var(--muted);font-size:12px;white-space:nowrap}.wifi-manager{margin-top:12px;background:var(--glass2)}.wifi-manager>summary:after{content:'+';margin-left:auto;color:var(--success);font-size:20px;font-weight:400}.wifi-manager[open]>summary:after{content:'−'}.saved-wifi-list{display:grid;grid-template-columns:minmax(0,1fr);gap:8px;margin:0;padding:9px}.saved-wifi-list>.hint{padding:6px 3px}.saved-wifi-item{display:grid;grid-template-columns:minmax(0,1fr) auto;align-items:center;gap:12px;width:100%;min-width:0;min-height:58px;padding:9px 10px;border:1px solid var(--line2);border-radius:9px;background:#0f192a}.saved-wifi-item.active{border-color:rgba(52,211,153,.5);background:rgba(4,120,87,.1);box-shadow:inset 3px 0 0 var(--success)}.wifi-profile-main{display:flex;align-items:center;gap:9px;min-width:0}.wifi-profile-dot{flex:0 0 auto;width:8px;height:8px;border-radius:50%;background:#64748b}.saved-wifi-item.active .wifi-profile-dot{background:var(--success);box-shadow:0 0 0 4px rgba(52,211,153,.12)}.wifi-profile-name{min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-weight:700}.wifi-profile-badge{flex:0 0 auto;display:inline-flex;align-items:center;min-height:24px;padding:2px 8px;border:1px solid rgba(52,211,153,.35);border-radius:999px;background:rgba(52,211,153,.1);color:#a7f3d0;font-size:10px;font-weight:800;letter-spacing:.03em;text-transform:uppercase}.wifi-profile-actions{display:flex;justify-content:flex-end;gap:7px}.wifi-profile-actions .btn{min-height:36px;padding:5px 11px;font-size:12px}@media(max-width:680px){.static{grid-template-columns:1fr}.network-live{grid-template-columns:1fr}.save{align-items:stretch;flex-direction:column}.wifi-tools .btn{width:100%}.saved-wifi-item{grid-template-columns:1fr;gap:9px}.wifi-profile-main{flex-wrap:wrap}.wifi-profile-actions{display:grid;grid-template-columns:repeat(auto-fit,minmax(82px,1fr));width:100%}.wifi-profile-actions .btn{width:100%}}</style></head><body data-page='it'><div class='shell'>"
"<header class='hero'><div class='brand'><img class='logo' src='/logo.png' alt='AUBOT'><div><div class='eyebrow'>AUBOT · WAREHOUSE GATEWAY</div><h1>Thiết lập kết nối</h1><p>Định danh thiết bị, WiFi và kết nối hệ thống</p></div></div><div data-app-user></div></header><div data-system-bar></div><nav class='nav' data-app-nav></nav>"
"<section class='network-live' aria-label='Địa chỉ mạng hiện tại' aria-live='polite'><article class='network-live-item'><div class='network-live-head'><small>AP CẤU HÌNH</small><span id='liveApState' class='network-state'>ĐANG ĐỌC</span></div><b id='liveApIp' class='network-ip'>" GATEWAY_AP_IP "</b><p id='liveApMeta' class='network-meta'>Mạng cục bộ của Gateway</p></article><article class='network-live-item'><div class='network-live-head'><small>WIFI STA</small><span id='liveStaState' class='network-state'>ĐANG ĐỌC</span></div><b id='liveStaIp' class='network-ip'>--</b><p id='liveStaMeta' class='network-meta'>Chưa kết nối router</p></article><article class='network-live-item'><div class='network-live-head'><small id='liveEthMode'>ETHERNET DEBUG</small><span id='liveEthState' class='network-state'>ĐANG ĐỌC</span></div><b id='liveEthIp' class='network-ip'>" GATEWAY_ETH_DEBUG_IP "</b><p id='liveEthMeta' class='network-meta'>Nối trực tiếp máy tính</p></article></section>"
"<form id='form'><main class='stack'><details class='card config' data-section open><summary><span class='step'>01</span><b>Định danh thiết bị</b></summary><div class='body'><div class='fields'><label class='field'><span>Mã công ty</span><input id='company_id' maxlength='31' pattern='[a-z0-9][a-z0-9_-]*' required></label><label class='field'><span>Mã địa điểm</span><input id='site_id' maxlength='31' pattern='[a-z0-9][a-z0-9_-]*' required></label><label class='field full'><span>Mã Gateway</span><input id='gateway_id' maxlength='16' pattern='[A-Za-z0-9][A-Za-z0-9_-]*' required></label></div><p class='hint' id='identityAccess'>Mã công ty và mã địa điểm do IT quản lý.</p><p class='hint'>Mã kho MQTT tự động: <b id='warehouseIdentity'>--</b></p><p class='hint'>Được tạo từ Mã Gateway: <b id='warehouseSource'>--</b></p><p class='hint'>Tên AP: <b id='apName'>--</b></p><div class='tools'><span id='stAp' class='hint'>Đang đọc AP</span><span><button class='btn ghost' type='button' id='apOn'>Bật AP</button> <button class='btn ghost' type='button' id='apOff'>Tắt AP</button></span></div></div></details>"
"<details class='card config' data-section><summary><span class='step'>02</span><b>WiFi</b></summary><div class='body'><div class='tools wifi-tools'><button class='btn secondary' type='button' id='scan'>Quét WiFi</button></div><div id='scanResults' class='wifi-results' aria-live='polite'></div><div class='fields'><label class='field full'><span>Tên WiFi</span><input id='wifi_ssid' list='nets' maxlength='32' autocomplete='off'><datalist id='nets'></datalist></label><label class='field full'><span>Mật khẩu WiFi</span><input id='wifi_password' type='password' maxlength='63' autocomplete='new-password' placeholder='Để trống để giữ mật khẩu đã lưu'></label><label class='field full'><span>Cấp địa chỉ</span><select id='wifi_dhcp'><option value='1'>DHCP tự động</option><option value='0'>IP tĩnh</option></select></label></div><div id='wifiStatic' class='static'><label class='field'><span>IP</span><input id='wifi_ip'></label><label class='field'><span>Subnet</span><input id='wifi_netmask'></label><label class='field'><span>Gateway</span><input id='wifi_gateway'></label><label class='field'><span>DNS</span><input id='wifi_dns'></label></div><details class='wifi-manager'><summary>Quản lý WiFi đã lưu</summary><div id='profiles' class='saved-wifi-list'></div></details></div></details>"
"<details class='card config hidden' id='ethSection' data-section><summary><span class='step'>03</span><b>Ethernet</b></summary><div class='body'><div class='segmented'><button class='btn' type='button' id='ethDebug'>DEBUG MÁY TÍNH</button><button class='btn' type='button' id='ethUplink'>KẾT NỐI ROUTER</button></div><p id='debugMode' class='mode-note'>IP cố định " GATEWAY_ETH_DEBUG_IP " /24 để nối trực tiếp máy tính. Máy tính đặt IP cùng dải 192.168.66.x.</p><div id='uplinkMode'><label class='field'><span>Cấp địa chỉ</span><select id='eth_dhcp'><option value='1'>DHCP từ router</option><option value='0'>IP tĩnh</option></select></label><div id='ethStatic' class='static'><label class='field'><span>IP</span><input id='eth_ip'></label><label class='field'><span>Subnet</span><input id='eth_netmask'></label><label class='field'><span>Gateway</span><input id='eth_gateway'></label><label class='field'><span>DNS</span><input id='eth_dns'></label></div></div></div></details>"
"<details class='card config hidden' id='mqttSection' data-section><summary><span class='step'>04</span><b>MQTT và thời gian</b></summary><div class='body'><div class='fields'><label class='field full'><span>Máy chủ MQTT</span><input id='mqtt_broker'></label><label class='field'><span>Cổng</span><input id='mqtt_port' type='number' min='1' max='65535'></label><label class='field'><span>Giao thức</span><select id='mqtt_transport'><option value='tcp'>TCP</option><option value='tls'>TLS</option></select></label><label class='field'><span>Tài khoản</span><input id='mqtt_user'></label><label class='field'><span>Mật khẩu</span><input id='mqtt_password' type='password' placeholder='Để trống nếu giữ nguyên'></label><label class='field full'><span>Chu kỳ gửi (ms)</span><input id='publish_interval_ms' type='number' min='250' max='60000'></label><label class='field full'><span>Máy chủ thời gian chính</span><input id='sntp_primary'></label><label class='field full'><span>Máy chủ thời gian dự phòng</span><input id='sntp_fallback'></label><label class='field full'><span>Múi giờ POSIX</span><input id='timezone'></label></div><div class='mode-note' style='margin-top:12px'><b>Topic trạng thái JSON</b><br><span id='topicJson'>warehouse/sensor/--/--/--/status/json</span><br><br><b>Topic trạng thái bit</b><br><span id='topicBits'>warehouse/sensor/--/--/--/status/bits</span></div><p class='hint'><span id='timeState'>Đang kiểm tra thời gian</span></p></div></details></main><footer class='toolbar save'><div id='feedback' class='message' aria-live='polite'>Chưa có thay đổi.</div><button class='btn primary' id='save'>Lưu cấu hình</button></footer></form></div>"
"<script src='/ui.js?v=5'></script><script>"
"const scanBox=document.getElementById('scanResults'),scanPanel=document.createElement('details'),scanTitle=document.createElement('summary');scanPanel.className='wifi-manager';scanTitle.textContent='Mạng WiFi tìm thấy';scanPanel.append(scanTitle);scanBox.before(scanPanel);scanPanel.append(scanBox);new MutationObserver(()=>{const n=scanBox.children.length;scanTitle.textContent=n?'Mạng WiFi tìm thấy ('+n+')':'Mạng WiFi tìm thấy';if(n)scanPanel.open=true}).observe(scanBox,{childList:true});"
"const $=x=>document.getElementById(x),base=['gateway_id','wifi_dhcp','wifi_ip','wifi_netmask','wifi_gateway','wifi_dns'],identity=['company_id','site_id'],eth=['eth_dhcp','eth_ip','eth_netmask','eth_gateway','eth_dns'],mq=['mqtt_broker','mqtt_port','mqtt_user','publish_interval_ms','sntp_primary','sntp_fallback','timezone'];let uplink=false,canEth=false,canMq=false,timer;"
"document.querySelectorAll('[data-section]').forEach(s=>s.ontoggle=()=>{if(s.open)document.querySelectorAll('[data-section][open]').forEach(o=>{if(o!==s)o.open=false})});"
"function feedback(text,ok){const f=$('feedback');f.className='message '+(ok===true?'ok':ok===false?'bad':'');f.textContent=text}"
"function authenticated(r){if(r.status!==401)return r;location.replace('/login');throw Error('Phiên đăng nhập đã hết hạn')}"
"function staticUi(){$('wifiStatic').classList.toggle('hidden',$('wifi_dhcp').value==='1');$('ethStatic').classList.toggle('hidden',$('eth_dhcp').value==='1')}"
"function ethUi(){$('ethDebug').classList.toggle('active',!uplink);$('ethUplink').classList.toggle('active',uplink);$('debugMode').classList.toggle('hidden',uplink);$('uplinkMode').classList.toggle('hidden',!uplink);staticUi()}"
"function showIdentity(){const gateway=$('gateway_id').value,valid=/^[A-Za-z0-9][A-Za-z0-9_-]{0,15}$/.test(gateway),warehouseId=valid?gateway.toLowerCase():'--',ap=valid?'AUBOT-'+gateway+'-<MAC6>':'--',topic='warehouse/sensor/'+($('company_id').value||'--')+'/'+($('site_id').value||'--')+'/'+warehouseId+'/status/';$('apName').textContent=ap;$('warehouseIdentity').textContent=warehouseId;$('warehouseSource').textContent=valid?gateway:'Mã Gateway chưa hợp lệ';$('topicJson').textContent=topic+'json';$('topicBits').textContent=topic+'bits'}"
"function chooseWifi(ssid,edit){$('wifi_ssid').value=ssid;$('wifi_password').value='';feedback(edit?'Đang sửa '+ssid+'. Nhập mật khẩu mới rồi bấm Lưu cấu hình.':'Đã chọn '+ssid+'. Gateway sẽ thử mạng này cùng các mạng đã lưu.');if(edit)$('wifi_password').focus();else $('wifi_ssid').focus()}"
"function renderProfiles(items){const box=$('profiles');box.textContent='';if(!items.length){const e=document.createElement('span');e.className='hint';e.textContent='Chưa lưu mạng WiFi';box.append(e);return}items.forEach(item=>{const p=typeof item==='string'?{ssid:item,active:false}:item,r=document.createElement('div'),main=document.createElement('div'),dot=document.createElement('i'),name=document.createElement('span'),actions=document.createElement('div');r.className='saved-wifi-item'+(p.active?' active':'');main.className='wifi-profile-main';dot.className='wifi-profile-dot';dot.setAttribute('aria-hidden','true');name.className='wifi-profile-name';name.textContent=p.ssid;actions.className='wifi-profile-actions';main.append(dot,name);if(p.active){const active=document.createElement('span');active.className='wifi-profile-badge';active.textContent='Đang dùng';main.append(active)}else{const use=document.createElement('button');use.type='button';use.className='btn ghost';use.textContent='Chọn';use.setAttribute('aria-label','Chọn mạng '+p.ssid);use.onclick=()=>chooseWifi(p.ssid,false);actions.append(use)}const edit=document.createElement('button');edit.type='button';edit.className='btn ghost';edit.textContent='Sửa';edit.setAttribute('aria-label','Sửa mạng '+p.ssid);edit.onclick=()=>chooseWifi(p.ssid,true);const del=document.createElement('button');del.type='button';del.className='btn danger';del.textContent='Xóa';del.setAttribute('aria-label','Xóa mạng '+p.ssid);del.onclick=()=>removeWifi(p.ssid,del,p.active);actions.append(edit,del);r.append(main,actions);box.append(r)})}"
"async function removeWifi(ssid,button,active){const detail=(active?'Gateway đang dùng mạng này. Xóa có thể làm gián đoạn kết nối WebUI.\\n\\n':'')+'Xóa mạng '+ssid+' khỏi Gateway?';if(!await gw.confirm(detail,{title:'Xác nhận xóa WiFi',confirmText:'Xóa mạng',danger:true}))return;button.disabled=true;try{const r=authenticated(await fetch('/api/it/wifi-profiles/delete',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:new URLSearchParams({ssid})}));if(!r.ok)throw Error(await r.text());if($('wifi_ssid').value===ssid){$('wifi_ssid').value='';$('wifi_password').value=''}feedback('Đã xóa mạng '+ssid+'.',true);setTimeout(load,500)}catch(e){feedback('Không thể xóa mạng: '+e.message,false);button.disabled=false}}"
"async function load(){const r=authenticated(await fetch('/api/it/config',{cache:'no-store'}));if(!r.ok)throw Error(await r.text());const c=await r.json();canEth=!!c.can_ethernet;canMq=!!c.can_mqtt;$('ethSection').classList.toggle('hidden',!canEth);$('mqttSection').classList.toggle('hidden',!canMq);[...base,...identity,...eth,...mq].forEach(k=>{if($(k))$(k).value=c[k]==null?'':c[k]});identity.forEach(k=>{$(k).disabled=!canMq;$(k).required=canMq});$('identityAccess').textContent=canMq?'Bạn có quyền sửa mã công ty và mã địa điểm. Mã MQTT của thiết bị được tạo tự động từ Mã Gateway.':'Mã công ty và mã địa điểm chỉ đọc; Mã MQTT được tạo tự động từ Mã Gateway.';uplink=!!c.eth_router_mode;$('mqtt_transport').value=c.mqtt_transport||'tcp';renderProfiles(c.wifi_profiles||[]);ethUi();showIdentity();poll()}"
"async function scan(){const b=$('scan'),box=$('scanResults');b.disabled=true;b.textContent='Đang quét…';box.textContent='';try{const r=authenticated(await fetch('/api/it/wifi-scan',{cache:'no-store'}));if(!r.ok)throw Error(await r.text());const d=await r.json();$('nets').textContent='';d.networks.forEach(x=>{const option=document.createElement('option');option.value=x.ssid;option.label=x.rssi+' dBm';$('nets').append(option);const row=document.createElement('div');row.className='wifi-row';const pick=document.createElement('button');pick.type='button';pick.textContent=x.ssid;pick.onclick=()=>chooseWifi(x.ssid,true);const quality=document.createElement('span');quality.className='wifi-rssi';quality.textContent=x.rssi+' dBm';row.append(pick,quality);box.append(row)});if(!d.networks.length)feedback('Không tìm thấy mạng WiFi. Hãy thử quét lại.')}catch(e){feedback('Quét WiFi thất bại: '+e.message,false)}finally{b.disabled=false;b.textContent='Quét WiFi'}}"
"function liveState(id,text,state){const e=$(id);e.textContent=text;e.className='network-state '+state}"
"async function poll(){clearTimeout(timer);if(document.hidden){timer=setTimeout(poll,10000);return}try{const d=await authenticated(await fetch('/api/it/status',{cache:'no-store'})).json(),eth=d.ethernet||{},wifi=d.wifi||{};$('stAp').textContent=d.ap?(d.ap_manual?'AP đang phát · thủ công · '+d.ap_ip:'AP đang phát · tự động · '+d.ap_ip):'AP đã tắt · '+(d.ap_ip||'--');$('liveApIp').textContent=d.ap_ip||'--';liveState('liveApState',d.ap?'ĐANG BẬT':'ĐÃ TẮT',d.ap?'ok':'warn');$('liveApMeta').textContent=d.ap?'Sẵn sàng cấu hình cục bộ':'IP cố định khi bật lại';$('liveStaIp').textContent=wifi.connected&&wifi.ip?wifi.ip:'--';liveState('liveStaState',wifi.connected?'KẾT NỐI':'OFFLINE',wifi.connected?'ok':'bad');$('liveStaMeta').textContent=wifi.connected?(wifi.ssid+(Number.isFinite(wifi.rssi)?' · '+wifi.rssi+' dBm':'')):'Chưa kết nối router WiFi';$('liveEthMode').textContent='ETHERNET '+(eth.mode==='UPLINK'?'UPLINK':'DEBUG');$('liveEthIp').textContent=eth.ip||'--';liveState('liveEthState',eth.link?(eth.connected?'KẾT NỐI':'ĐANG LẤY IP'):'CHƯA CẮM CÁP',eth.link?(eth.connected?'ok':'warn'):'bad');$('liveEthMeta').textContent=eth.mode==='UPLINK'?'Kết nối router':'Nối trực tiếp máy tính';$('timeState').textContent=d.time_valid?'Thời gian đã đồng bộ':'Thời gian chưa đồng bộ'}catch(e){$('stAp').textContent='Mất cập nhật trạng thái kết nối';liveState('liveApState','MẤT DỮ LIỆU','bad');liveState('liveStaState','MẤT DỮ LIỆU','bad');liveState('liveEthState','MẤT DỮ LIỆU','bad')}timer=setTimeout(poll,3000)}"
"async function ap(v){const r=authenticated(await fetch('/api/it/ap',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:new URLSearchParams({enabled:v?1:0})}));if(!r.ok)feedback('Không thể đổi trạng thái AP: '+await r.text(),false);poll()}"
"$('scan').onclick=scan;$('apOn').onclick=()=>ap(true);$('apOff').onclick=()=>ap(false);$('gateway_id').oninput=$('company_id').oninput=$('site_id').oninput=showIdentity;$('wifi_dhcp').onchange=$('eth_dhcp').onchange=staticUi;$('ethDebug').onclick=()=>{uplink=false;ethUi()};$('ethUplink').onclick=()=>{uplink=true;ethUi()};document.addEventListener('visibilitychange',()=>{if(!document.hidden)poll()});"
"$('form').onsubmit=async e=>{e.preventDefault();const p=new URLSearchParams();base.forEach(k=>p.set(k,$(k).value));if(canMq)identity.forEach(k=>p.set(k,$(k).value));if(canEth){eth.forEach(k=>p.set(k,$(k).value));p.set('eth_router_mode',uplink?1:0)}if(canMq){mq.forEach(k=>p.set(k,$(k).value));p.set('mqtt_transport',$('mqtt_transport').value);p.set('mqtt_password',$('mqtt_password').value)}p.set('wifi_ssid',$('wifi_ssid').value);p.set('wifi_password',$('wifi_password').value);const b=$('save');b.disabled=true;feedback('Đang lưu…');try{const r=authenticated(await fetch('/api/it/config',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:p}));if(!r.ok)throw Error(await r.text());$('wifi_password').value='';feedback('Đã lưu và áp dụng đúng phần cấu hình thay đổi.',true);setTimeout(load,700)}catch(x){feedback('Không thể lưu: '+x.message,false)}finally{b.disabled=false}};load().catch(e=>feedback('Không thể đọc cấu hình: '+e.message,false))"
"</script></body></html>";
